/* BOI 360 Page - Futuristic 3D Command Center (dark + yellow/gold). Canvas 1280 x 720, scaled to the viewport. */
.bx-host {
  background: #090B0F;
  font-family: 'Segoe UI', 'Bahnschrift', Arial, sans-serif;
}
.bx-page {
  position: absolute;
  left: 0;
  top: 0;
  width: 1280px;
  height: 720px;
  box-sizing: border-box;
  padding: 10px;
  display: flex;
  gap: 10px;
  transform-origin: 0 0;
  color: #F5F7FA;
  font-size: 11px;
  overflow: hidden;
  background: radial-gradient(520px 300px at 58% -6%, rgba(255, 212, 59, 0.13), transparent 70%), radial-gradient(420px 320px at 100% 100%, rgba(245, 184, 46, 0.08), transparent 70%), linear-gradient(180deg, #090B0F 0%, #0B0E13 100%);
  /* perspective grid floor */
  /* fine technical dot pattern */
}
.bx-page * {
  box-sizing: border-box;
}
.bx-page button,
.bx-page select,
.bx-page input {
  font-family: inherit;
}
.bx-page::before {
  content: "";
  position: absolute;
  left: -20%;
  right: -20%;
  bottom: -38%;
  height: 70%;
  background-image: linear-gradient(rgba(255, 212, 59, 0.08) 1px, transparent 1px), linear-gradient(90deg, rgba(255, 212, 59, 0.08) 1px, transparent 1px);
  background-size: 46px 46px;
  transform: perspective(520px) rotateX(62deg);
  mask-image: linear-gradient(to top, rgba(0, 0, 0, 0.9), transparent 75%);
  -webkit-mask-image: linear-gradient(to top, rgba(0, 0, 0, 0.9), transparent 75%);
  pointer-events: none;
}
.bx-page::after {
  content: "";
  position: absolute;
  inset: 0;
  background-image: radial-gradient(rgba(255, 255, 255, 0.035) 1px, transparent 1px);
  background-size: 14px 14px;
  pointer-events: none;
}
.bx-empty {
  margin: auto;
  color: #A4ADBA;
  font-size: 16px;
}
/* ---------- sidebar ---------- */
.bx-side {
  position: relative;
  z-index: 1;
  flex: 0 0 172px;
  display: flex;
  flex-direction: column;
  gap: 6px;
  padding: 14px 10px 12px;
  border-radius: 16px;
  border: 1px solid rgba(255, 255, 255, 0.06);
  background: linear-gradient(180deg, rgba(32, 40, 51, 0.92), rgba(17, 21, 28, 0.94));
  box-shadow: 0 20px 40px rgba(0, 0, 0, 0.55), inset 0 1px 0 rgba(255, 255, 255, 0.05), inset -1px 0 0 rgba(255, 212, 59, 0.1);
}
.bx-brand-block {
  display: flex;
  align-items: center;
  gap: 9px;
  padding: 0 4px 10px;
  border-bottom: 1px solid rgba(255, 212, 59, 0.12);
}
.bx-logo {
  filter: drop-shadow(0 0 8px rgba(255, 212, 59, 0.55));
}
.bx-brand {
  font-size: 15px;
  font-weight: 800;
  letter-spacing: 2.5px;
  color: #FFD43B;
  text-shadow: 0 0 12px rgba(255, 212, 59, 0.45);
}
.bx-brand-sub {
  color: #A4ADBA;
  font-size: 9px;
  letter-spacing: 0.6px;
  text-transform: uppercase;
}
.bx-side-label {
  margin: 8px 6px 2px;
  color: #687383;
  font-size: 8.5px;
  letter-spacing: 1.4px;
  text-transform: uppercase;
}
.bx-nav {
  display: flex;
  flex-direction: column;
  gap: 2px;
}
.bx-nav-item {
  position: relative;
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 8px 9px;
  border-radius: 9px;
  color: #A4ADBA;
  font-size: 10.5px;
  cursor: pointer;
  transition: background 0.25s, color 0.25s;
}
.bx-nav-item svg {
  color: #687383;
  flex: 0 0 auto;
  transition: color 0.25s;
}
.bx-nav-item:hover {
  background: rgba(255, 255, 255, 0.04);
  color: #F5F7FA;
}
.bx-nav-item::before {
  content: "";
  position: absolute;
  left: -10px;
  top: 6px;
  bottom: 6px;
  width: 3px;
  border-radius: 0 3px 3px 0;
  background: #FFD43B;
  box-shadow: 0 0 12px #FFD43B;
  transform: scaleY(0);
  transition: transform 0.35s cubic-bezier(0.2, 0.8, 0.2, 1);
}
.bx-nav-num {
  color: #687383;
  font-size: 8.5px;
  font-variant-numeric: tabular-nums;
}
.bx-nav-on {
  color: #F5F7FA;
  font-weight: 600;
  background: linear-gradient(90deg, rgba(255, 212, 59, 0.16), rgba(255, 212, 59, 0.02));
  box-shadow: inset 0 0 0 1px rgba(255, 212, 59, 0.22);
}
.bx-nav-on::before {
  transform: scaleY(1);
}
.bx-nav-on svg,
.bx-nav-on .bx-nav-num {
  color: #FFD43B;
}
.bx-side-status {
  margin-top: auto;
  padding: 9px 8px 2px;
  border-top: 1px solid rgba(255, 212, 59, 0.12);
  display: flex;
  flex-direction: column;
  gap: 2px;
  font-size: 9.5px;
}
.bx-live {
  display: flex;
  align-items: center;
  gap: 6px;
  color: #F5F7FA;
  font-weight: 600;
}
.bx-live-dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: #35D39A;
  box-shadow: 0 0 8px #35D39A;
  animation: bx-breathe 2.4s ease-in-out infinite;
}
/* ---------- main column ---------- */
.bx-main {
  position: relative;
  z-index: 1;
  flex: 1 1 auto;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.bx-header {
  flex: 0 0 auto;
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 2px 2px 0;
}
.bx-eyebrow {
  color: #F5B82E;
  font-size: 9px;
  letter-spacing: 1.6px;
  text-transform: uppercase;
}
.bx-title-row {
  display: flex;
  align-items: center;
  gap: 9px;
  margin-top: 2px;
}
.bx-badge {
  display: inline-flex;
  width: 28px;
  height: 28px;
  border-radius: 8px;
  align-items: center;
  justify-content: center;
  color: #1A1405;
  background: linear-gradient(135deg, #FFF0A3, #FFD43B 45%, #C98F12);
  box-shadow: 0 0 16px rgba(255, 212, 59, 0.45), inset 0 1px 0 rgba(255, 255, 255, 0.6);
}
.bx-title {
  font-size: 21px;
  font-weight: 700;
  letter-spacing: 0.2px;
}
.bx-subtitle {
  margin: 2px 0 0 37px;
  color: #A4ADBA;
  font-size: 10px;
}
.bx-head-actions {
  display: flex;
  align-items: center;
  gap: 8px;
}
.bx-chip {
  display: flex;
  align-items: center;
  gap: 7px;
  padding: 5px 10px;
  border-radius: 10px;
  border: 1px solid rgba(255, 255, 255, 0.06);
  background: rgba(32, 40, 51, 0.75);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.04);
}
.bx-chip svg {
  color: #FFD43B;
}
.bx-chip-label {
  color: #687383;
  font-size: 8.5px;
  text-transform: uppercase;
  letter-spacing: 0.8px;
}
.bx-chip-value {
  color: #F5F7FA;
  font-size: 10.5px;
  font-weight: 600;
}
.bx-bell,
.bx-user {
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 34px;
  height: 34px;
  border-radius: 50%;
  border: 1px solid rgba(255, 255, 255, 0.06);
  background: rgba(32, 40, 51, 0.8);
  color: #A4ADBA;
}
.bx-bell svg {
  color: #FFD43B;
}
.bx-user {
  background: linear-gradient(135deg, rgba(255, 212, 59, 0.25), rgba(32, 40, 51, 0.9));
  color: #FFF0A3;
}
.bx-bell-count {
  position: absolute;
  top: -4px;
  right: -6px;
  min-width: 17px;
  height: 17px;
  padding: 0 4px;
  border-radius: 9px;
  background: #FF5C64;
  color: #fff;
  font-size: 9px;
  font-weight: 700;
  line-height: 17px;
  text-align: center;
  box-shadow: 0 0 10px rgba(255, 92, 100, 0.7);
}
.bx-pulse::after {
  content: "";
  position: absolute;
  inset: -3px;
  border-radius: 50%;
  border: 1px solid rgba(255, 92, 100, 0.7);
  animation: bx-ping 2.2s ease-out infinite;
}
.bx-reset,
.bx-primary,
.ac-btn {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 7px 12px;
  border-radius: 10px;
  border: 1px solid rgba(255, 212, 59, 0.55);
  background: linear-gradient(180deg, rgba(255, 212, 59, 0.16), rgba(255, 212, 59, 0.06));
  color: #F5F7FA;
  font-size: 10.5px;
  font-weight: 600;
  cursor: pointer;
  transition: background 0.2s, box-shadow 0.2s, transform 0.15s;
}
.bx-reset svg,
.bx-primary svg,
.ac-btn svg {
  color: #FFD43B;
}
.bx-reset:hover,
.bx-primary:hover,
.ac-btn:hover {
  background: rgba(255, 212, 59, 0.24);
  box-shadow: 0 0 16px rgba(255, 212, 59, 0.35);
  transform: translateY(-1px);
}
.bx-reset:disabled,
.bx-primary:disabled,
.ac-btn:disabled {
  opacity: 0.3;
  cursor: default;
  box-shadow: none;
  transform: none;
}
/* ---------- filters ---------- */
.bx-filters {
  flex: 0 0 auto;
  display: flex;
  gap: 7px;
  align-items: stretch;
}
.bx-filter {
  display: flex;
  flex-direction: column;
  gap: 3px;
  width: 140px;
  padding: 5px 8px 6px;
  border-radius: 10px;
  border: 1px solid rgba(255, 255, 255, 0.06);
  background: rgba(23, 29, 38, 0.88);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.03);
}
.bx-period {
  width: 236px;
}
.bx-period-row {
  display: flex;
  align-items: center;
  gap: 5px;
}
.bx-period-sep {
  color: #F5B82E;
}
.bx-filter-label {
  display: flex;
  align-items: center;
  gap: 4px;
  color: #687383;
  font-size: 8.5px;
  font-weight: 600;
  letter-spacing: 0.9px;
  text-transform: uppercase;
}
.bx-filter-label svg {
  color: #F5B82E;
}
.bx-select,
.ac-input {
  width: 100%;
  height: 23px;
  padding: 0 6px;
  border-radius: 6px;
  border: 1px solid rgba(255, 255, 255, 0.08);
  background: #0E1218;
  color: #F5F7FA;
  font-size: 10.5px;
  outline: none;
  transition: border-color 0.2s, box-shadow 0.2s;
}
.bx-select:hover,
.ac-input:hover {
  border-color: rgba(255, 212, 59, 0.35);
}
.bx-select:focus,
.ac-input:focus {
  border-color: #FFD43B;
  box-shadow: 0 0 0 2px rgba(255, 212, 59, 0.2);
}
.bx-select option,
.ac-input option {
  background: #11151C;
  color: #F5F7FA;
}
.bx-select-on {
  border-color: #FFD43B;
  color: #FFF0A3;
  box-shadow: 0 0 10px rgba(255, 212, 59, 0.28);
}
/* ---------- KPI floating panels ---------- */
.bx-kpis {
  flex: 0 0 96px;
  display: grid;
  grid-template-columns: repeat(6, 1fr);
  gap: 9px;
}
.bx-kpi {
  position: relative;
  display: flex;
  flex-direction: column;
  padding: 8px 11px 6px;
  border-radius: 13px;
  border: 1px solid rgba(255, 255, 255, 0.06);
  background: linear-gradient(160deg, #202833 0%, #171D26 55%, #141920 100%);
  box-shadow: 0 1px 0 rgba(255, 255, 255, 0.06) inset, 0 -1px 0 rgba(0, 0, 0, 0.4) inset, 0 10px 18px rgba(0, 0, 0, 0.45), 0 22px 34px -14px rgba(0, 0, 0, 0.7);
  overflow: hidden;
  transition: transform 0.25s, box-shadow 0.25s, border-color 0.25s;
  --tone: #FFD43B;
  /* gold edge light */
}
.bx-kpi::before {
  content: "";
  position: absolute;
  left: 12px;
  right: 12px;
  top: 0;
  height: 1px;
  background: linear-gradient(90deg, transparent, var(--tone), transparent);
  opacity: 0.9;
}
.bx-kpi:hover {
  transform: translateY(-2px);
  border-color: rgba(255, 212, 59, 0.35);
  box-shadow: 0 1px 0 rgba(255, 255, 255, 0.06) inset, 0 14px 26px rgba(0, 0, 0, 0.5), 0 0 22px rgba(255, 212, 59, 0.16);
}
.bx-kpi.bx-violet {
  --tone: #F5B82E;
}
.bx-kpi.bx-blue {
  --tone: #7F8EA3;
}
.bx-kpi.bx-good {
  --tone: #35D39A;
}
.bx-kpi.bx-warn {
  --tone: #FFB84D;
}
.bx-kpi.bx-bad {
  --tone: #FF5C64;
}
.bx-kpi-top {
  display: flex;
  align-items: center;
  gap: 6px;
  color: #A4ADBA;
  font-size: 9.5px;
}
.bx-kpi-icon {
  display: inline-flex;
  color: var(--tone);
}
.bx-kpi-label {
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.bx-alert-dot {
  margin-left: auto;
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: #FF5C64;
  box-shadow: 0 0 8px #FF5C64;
  animation: bx-breathe 1.6s ease-in-out infinite;
}
.bx-kpi-mid {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 6px;
  margin-top: 2px;
  min-width: 0;
}
.bx-kpi-mid .bx-kpi-value {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
}
.bx-kpi-value {
  font-size: 21px;
  font-weight: 700;
  white-space: nowrap;
  font-variant-numeric: tabular-nums;
  color: #F5F7FA;
  text-shadow: 0 0 18px rgba(255, 212, 59, 0.18);
}
.bx-kpi:first-child .bx-kpi-value {
  color: #FFD43B;
  text-shadow: 0 0 18px rgba(255, 212, 59, 0.45);
}
.bx-kpi.bx-good .bx-kpi-value {
  color: #35D39A;
}
.bx-kpi.bx-warn .bx-kpi-value {
  color: #FFB84D;
}
.bx-kpi.bx-bad .bx-kpi-value {
  color: #FF5C64;
}
.bx-kpi-foot {
  display: flex;
  align-items: center;
  gap: 5px;
  margin-top: 2px;
  min-width: 0;
  position: relative;
  z-index: 1;
}
.bx-kpi-note {
  color: #687383;
  font-size: 9px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.bx-delta {
  flex: 0 0 auto;
  padding: 1px 5px;
  border-radius: 5px;
  font-size: 9px;
  font-weight: 700;
  color: #A4ADBA;
  background: rgba(255, 255, 255, 0.06);
}
.bx-delta-good {
  color: #35D39A;
  background: rgba(53, 211, 154, 0.12);
}
.bx-delta-bad {
  color: #FF5C64;
  background: rgba(255, 92, 100, 0.12);
}
.bx-spark {
  position: absolute;
  left: 0;
  right: 0;
  bottom: 0;
  width: 100%;
  height: 26px;
  opacity: 0.9;
  pointer-events: none;
}
.bx-spark-line {
  fill: none;
  stroke: var(--tone);
  stroke-width: 1.4;
  vector-effect: non-scaling-stroke;
  filter: drop-shadow(0 0 3px var(--tone));
}
.bx-spark-area {
  fill: var(--tone);
  opacity: 0.08;
}
.bx-ring {
  flex: 0 0 auto;
  filter: drop-shadow(0 0 6px rgba(0, 0, 0, 0.6));
}
.bx-ring-track {
  fill: none;
  stroke: rgba(255, 255, 255, 0.07);
  stroke-width: 5;
}
.bx-ring-arc {
  fill: none;
  stroke-width: 5;
  stroke-linecap: round;
  filter: drop-shadow(0 0 4px currentColor);
}
/* ---------- cards ---------- */
.bx-row {
  flex: 1 1 0;
  min-height: 0;
  display: grid;
  gap: 9px;
}
.bx-card {
  position: relative;
  display: flex;
  flex-direction: column;
  min-width: 0;
  min-height: 0;
  padding: 9px 11px 8px;
  border-radius: 14px;
  border: 1px solid rgba(255, 255, 255, 0.06);
  background: linear-gradient(165deg, rgba(32, 40, 51, 0.92) 0%, rgba(23, 29, 38, 0.95) 45%, rgba(18, 23, 30, 0.96) 100%);
  box-shadow: 0 1px 0 rgba(255, 255, 255, 0.05) inset, 0 16px 32px rgba(0, 0, 0, 0.5), 0 2px 0 rgba(0, 0, 0, 0.35);
  backdrop-filter: blur(10px);
  transition: border-color 0.25s, box-shadow 0.25s;
  /* corner brackets: command-center frame */
}
.bx-card::before,
.bx-card::after {
  content: "";
  position: absolute;
  width: 12px;
  height: 12px;
  border-color: rgba(255, 212, 59, 0.55);
  border-style: solid;
  pointer-events: none;
}
.bx-card::before {
  top: -1px;
  left: -1px;
  border-width: 1.5px 0 0 1.5px;
  border-radius: 14px 0 0 0;
}
.bx-card::after {
  bottom: -1px;
  right: -1px;
  border-width: 0 1.5px 1.5px 0;
  border-radius: 0 0 14px 0;
}
.bx-card:hover {
  border-color: rgba(255, 212, 59, 0.25);
  box-shadow: 0 1px 0 rgba(255, 255, 255, 0.05) inset, 0 18px 36px rgba(0, 0, 0, 0.55), 0 0 24px rgba(255, 212, 59, 0.1);
}
.bx-card-head {
  flex: 0 0 auto;
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 2px 8px;
  margin-bottom: 4px;
}
.bx-card-title {
  display: flex;
  align-items: center;
  gap: 5px;
  font-size: 11.5px;
  font-weight: 700;
  letter-spacing: 0.2px;
}
.bx-card-title svg {
  color: #FFD43B;
  filter: drop-shadow(0 0 4px rgba(255, 212, 59, 0.6));
}
.bx-card-sub {
  flex-basis: 100%;
  color: #687383;
  font-size: 9px;
}
.bx-card-body {
  position: relative;
  flex: 1 1 auto;
  min-height: 0;
  display: flex;
  flex-direction: column;
}
.bx-chart {
  flex: 1 1 auto;
  min-height: 0;
  position: relative;
}
.bx-nodata {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  color: #687383;
}
.bx-count {
  margin-left: auto;
  color: #687383;
  font-size: 9px;
}
.bx-search {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 0 7px;
  height: 21px;
  border-radius: 6px;
  border: 1px solid rgba(255, 255, 255, 0.08);
  background: #0E1218;
  color: #F5B82E;
}
.bx-search input {
  width: 105px;
  border: 0;
  outline: 0;
  background: transparent;
  color: #F5F7FA;
  font-size: 10px;
}
/* ---------- health core (Overview centrepiece) ---------- */
.bx-core {
  flex: 1 1 auto;
  min-height: 0;
  display: flex;
  align-items: center;
  gap: 10px;
}
.bx-core-dial {
  position: relative;
  flex: 0 0 auto;
  height: 100%;
  max-height: 150px;
  aspect-ratio: 1;
  background: radial-gradient(circle, rgba(255, 212, 59, 0.14) 0%, rgba(255, 212, 59, 0.03) 45%, transparent 70%);
  border-radius: 50%;
}
.bx-core-svg {
  width: 100%;
  height: 100%;
  animation: bx-spin-in 1.2s cubic-bezier(0.2, 0.8, 0.2, 1) both;
}
.bx-page:not(.bx-enter) .bx-core-svg {
  animation: none;
}
.bx-tick {
  stroke: rgba(255, 212, 59, 0.18);
  stroke-width: 1;
}
.bx-tick-major {
  stroke: rgba(255, 212, 59, 0.5);
}
.bx-core-track {
  fill: none;
  stroke: rgba(255, 255, 255, 0.06);
  stroke-width: 8;
}
.bx-core-arc {
  fill: none;
  stroke-width: 8;
  stroke-linecap: round;
  filter: drop-shadow(0 0 5px rgba(255, 212, 59, 0.35));
}
.bx-core-center {
  position: absolute;
  inset: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  pointer-events: none;
}
.bx-core-value {
  color: #FFD43B;
  font-size: 11px;
  font-weight: 800;
  text-shadow: 0 0 14px rgba(255, 212, 59, 0.55);
}
.bx-core-label {
  color: #687383;
  font-size: 8.5px;
  text-transform: uppercase;
  letter-spacing: 1px;
}
.bx-core-legend {
  flex: 1 1 auto;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 6px;
}
.bx-core-row {
  display: grid;
  grid-template-columns: 9px minmax(0, 1fr) auto;
  align-items: center;
  gap: 6px;
  padding: 4px 6px;
  border-radius: 8px;
  background: rgba(255, 255, 255, 0.025);
}
.bx-core-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
}
.bx-core-name {
  font-size: 10px;
  font-weight: 600;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.bx-core-note {
  color: #687383;
  font-size: 8.5px;
