/* ---------- entrance motion (first display of a page or new data only) ---------- */
.bx-enter .bx-side {
  animation: bx-slide-right 0.6s cubic-bezier(0.2, 0.8, 0.2, 1) both;
}
.bx-enter .bx-header,
.bx-enter .bx-filters {
  animation: bx-fade-up 0.5s ease-out both;
}
.bx-enter .bx-kpi {
  animation: bx-rise 0.6s cubic-bezier(0.2, 0.8, 0.2, 1) both;
}
.bx-enter .bx-card {
  animation: bx-rise 0.7s cubic-bezier(0.2, 0.8, 0.2, 1) both;
}
.bx-enter .bx-row:nth-of-type(2) .bx-card {
  animation-delay: 0.12s;
}
.bx-enter .bx-row .bx-card:nth-child(2) {
  animation-delay: 0.18s;
}
.bx-enter .bx-row .bx-card:nth-child(3) {
  animation-delay: 0.26s;
}
.bx-enter .bx-ring-arc,
.bx-enter .bx-core-arc {
  animation: bx-ring 1.3s cubic-bezier(0.2, 0.8, 0.2, 1) both;
}
.bx-enter .bx-spark-line {
  stroke-dasharray: 400;
  animation: bx-draw 1.4s ease-out both;
}
@keyframes bx-rise {
  from {
    opacity: 0;
    transform: translateY(14px) scale(0.985);
  }
  to {
    opacity: 1;
    transform: none;
  }
}
@keyframes bx-fade-up {
  from {
    opacity: 0;
    transform: translate(var(--tx, 0), 8px);
  }
  to {
    opacity: 1;
    transform: translate(var(--tx, 0), 0);
  }
}
@keyframes bx-slide-right {
  from {
    opacity: 0;
    transform: translateX(-16px);
  }
  to {
    opacity: 1;
    transform: none;
  }
}
@keyframes bx-slide-in {
  from {
    opacity: 0;
    transform: translateX(30px);
  }
  to {
    opacity: 1;
    transform: none;
  }
}
@keyframes bx-pop {
  from {
    opacity: 0;
    transform: translate(-50%, -48%) scale(0.97);
  }
  to {
    opacity: 1;
    transform: translate(-50%, -50%);
  }
}
@keyframes bx-ring {
  from {
    stroke-dashoffset: var(--ring-from);
  }
  to {
    stroke-dashoffset: var(--ring-to);
  }
}
@keyframes bx-draw {
  from {
    stroke-dashoffset: 400;
  }
  to {
    stroke-dashoffset: 0;
  }
}
@keyframes bx-spin-in {
  from {
    opacity: 0;
    transform: rotate(-35deg) scale(0.92);
  }
  to {
    opacity: 1;
    transform: none;
  }
}
@keyframes bx-breathe {
  0%,
  100% {
    opacity: 1;
  }
  50% {
    opacity: 0.35;
  }
}
@keyframes bx-ping {
  0% {
    transform: scale(1);
    opacity: 0.8;
  }
  80%,
  100% {
    transform: scale(1.6);
    opacity: 0;
  }
}
@media (prefers-reduced-motion: reduce) {
  .bx-page * {
    animation: none !important;
    transition: none !important;
  }
}
